"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";

export type PaymentMethodState = { error: string | null };

export async function addPaymentMethod(
  businessId: string,
  _prevState: PaymentMethodState,
  formData: FormData,
): Promise<PaymentMethodState> {
  const name = (formData.get("name") as string)?.trim();

  if (!name) {
    return { error: "Nama metode pembayaran wajib diisi." };
  }

  const supabase = await createClient();
  const { error } = await supabase.from("custom_payment_methods").insert({
    business_id: businessId,
    name,
  });

  if (error) {
    return { error: error.message };
  }

  revalidatePath(`/business/${businessId}/settings`);
  return { error: null };
}

export async function deletePaymentMethod(businessId: string, methodId: string) {
  const supabase = await createClient();
  await supabase.from("custom_payment_methods").delete().eq("id", methodId).eq("business_id", businessId);
  revalidatePath(`/business/${businessId}/settings`);
}

export type KitchenPrinterState = { error: string | null };

export async function addKitchenPrinter(
  businessId: string,
  _prevState: KitchenPrinterState,
  formData: FormData,
): Promise<KitchenPrinterState> {
  const name = (formData.get("name") as string)?.trim();
  const connectionType = formData.get("connectionType") as string;
  const address = (formData.get("address") as string)?.trim();
  const categories = formData.getAll("categories").map((c) => String(c));

  if (!name) {
    return { error: "Nama stasiun printer wajib diisi." };
  }
  if (connectionType !== "bluetooth" && connectionType !== "lan") {
    return { error: "Pilih jenis koneksi dulu." };
  }

  const supabase = await createClient();
  const { error } = await supabase.from("kitchen_printers").insert({
    business_id: businessId,
    name,
    connection_type: connectionType,
    address: address || null,
    categories,
  });

  if (error) {
    return { error: error.message };
  }

  revalidatePath(`/business/${businessId}/settings`);
  return { error: null };
}

export async function deleteKitchenPrinter(businessId: string, printerId: string) {
  const supabase = await createClient();
  await supabase.from("kitchen_printers").delete().eq("id", printerId).eq("business_id", businessId);
  revalidatePath(`/business/${businessId}/settings`);
}

"use client";

import { useActionState, useRef, useState, useEffect } from "react";
import type { KitchenPrinterState } from "./actions";

const initialState: KitchenPrinterState = { error: null };

export default function AddPrinterForm({
  action,
  categories,
}: {
  action: (state: KitchenPrinterState, formData: FormData) => Promise<KitchenPrinterState>;
  categories: string[];
}) {
  const [state, formAction, pending] = useActionState(action, initialState);
  const formRef = useRef<HTMLFormElement>(null);
  const [connectionType, setConnectionType] = useState<"bluetooth" | "lan">("bluetooth");

  useEffect(() => {
    if (!pending && !state.error) {
      formRef.current?.reset();
    }
  }, [pending, state.error]);

  return (
    <form ref={formRef} action={formAction} className="space-y-3">
      <div>
        <label htmlFor="printer-name" className="mb-1 block text-xs font-medium text-zinc-600">
          Nama Stasiun
        </label>
        <input
          id="printer-name"
          name="name"
          type="text"
          required
          placeholder="Contoh: Dapur, Bar, Bakery…"
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
      </div>

      <div>
        <p className="mb-1 text-xs font-medium text-zinc-600">Jenis Koneksi</p>
        <div className="grid grid-cols-2 gap-2">
          <button
            type="button"
            onClick={() => setConnectionType("bluetooth")}
            className={`rounded-xl border-2 p-2.5 text-left text-xs font-semibold transition-colors ${
              connectionType === "bluetooth"
                ? "border-brand-500 bg-brand-50 text-zinc-900"
                : "border-zinc-200 bg-white text-zinc-600"
            }`}
          >
            📶 Bluetooth
          </button>
          <button
            type="button"
            onClick={() => setConnectionType("lan")}
            className={`rounded-xl border-2 p-2.5 text-left text-xs font-semibold transition-colors ${
              connectionType === "lan"
                ? "border-brand-500 bg-brand-50 text-zinc-900"
                : "border-zinc-200 bg-white text-zinc-600"
            }`}
          >
            🌐 LAN / Wi-Fi
          </button>
        </div>
        <input type="hidden" name="connectionType" value={connectionType} />
      </div>

      <div>
        <label htmlFor="printer-address" className="mb-1 block text-xs font-medium text-zinc-600">
          {connectionType === "lan" ? "IP Address Printer" : "Nama Perangkat Bluetooth"}
        </label>
        <input
          id="printer-address"
          name="address"
          type="text"
          placeholder={connectionType === "lan" ? "192.168.1.101" : "Contoh: KITCHEN-80"}
          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm font-mono focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
        />
      </div>

      {categories.length > 0 && (
        <div>
          <p className="mb-1.5 text-xs font-medium text-zinc-600">
            Kategori Menu yang Dicetak ke Stasiun Ini
          </p>
          <div className="flex flex-wrap gap-2">
            {categories.map((c) => (
              <label
                key={c}
                className="flex items-center gap-1.5 rounded-full border border-zinc-200 bg-white px-3 py-1.5 text-xs text-zinc-700 has-checked:border-brand-500 has-checked:bg-brand-50"
              >
                <input type="checkbox" name="categories" value={c} className="h-3 w-3" />
                {c}
              </label>
            ))}
          </div>
        </div>
      )}

      {state.error && <p className="text-xs text-red-600">{state.error}</p>}

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
      >
        {pending ? "Menyimpan…" : "+ Tambah Printer"}
      </button>
    </form>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { createClient } from "@/lib/supabase/server";
import { addKitchenPrinter, addPaymentMethod } from "./actions";
import AddPaymentMethodForm from "./add-payment-method-form";
import AddPrinterForm from "./add-printer-form";
import DeletePaymentMethodButton from "./delete-payment-method-button";
import DeletePrinterButton from "./delete-printer-button";

export default async function SettingsPage({
  params,
}: {
  params: Promise<{ businessId: string }>;
}) {
  const { businessId } = await params;
  const supabase = await createClient();

  const { data: business } = await supabase
    .from("businesses")
    .select("id, name, business_type")
    .eq("id", businessId)
    .single();

  if (!business) {
    notFound();
  }

  const isFnb = business.business_type === "fnb";

  const { data: paymentMethods } = await supabase
    .from("custom_payment_methods")
    .select("id, name")
    .eq("business_id", businessId)
    .order("name", { ascending: true });

  const boundAddPaymentMethod = addPaymentMethod.bind(null, businessId);

  let printers: { id: string; name: string; categories: string[]; connection_type: string; address: string | null }[] = [];
  let productCategories: string[] = [];

  if (isFnb) {
    const { data: printerRows } = await supabase
      .from("kitchen_printers")
      .select("id, name, categories, connection_type, address")
      .eq("business_id", businessId)
      .order("name", { ascending: true });
    printers = printerRows ?? [];

    const { data: categoryRows } = await supabase
      .from("products")
      .select("category")
      .eq("business_id", businessId)
      .is("deleted_at", null)
      .not("category", "is", null);
    productCategories = Array.from(
      new Set((categoryRows ?? []).map((r) => r.category as string).filter(Boolean)),
    ).sort();
  }

  const boundAddKitchenPrinter = addKitchenPrinter.bind(null, businessId);

  return (
    <div className="flex flex-1 flex-col items-center bg-zinc-50 px-4 py-10">
      <div className="w-full max-w-sm">
        <Link href="/dashboard" className="text-xs font-medium text-zinc-500 hover:underline">
          ← Kembali ke dashboard
        </Link>

        <h1 className="mt-3 text-lg font-bold text-zinc-900">Pengaturan — {business.name}</h1>

        {/* Metode Pembayaran Custom */}
        <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
          <h2 className="text-sm font-semibold text-zinc-900">Metode Pembayaran Custom</h2>
          <p className="mt-1 text-xs text-zinc-500">
            Tambahan di luar Tunai, Kartu, QRIS — misalnya dompet digital atau transfer bank
            tertentu.
          </p>

          <div className="mt-4 space-y-2">
            {paymentMethods && paymentMethods.length > 0 ? (
              paymentMethods.map((m) => (
                <div
                  key={m.id}
                  className="flex items-center justify-between rounded-xl border border-zinc-200 bg-white px-4 py-2.5"
                >
                  <p className="text-sm font-medium text-zinc-900">{m.name}</p>
                  <DeletePaymentMethodButton businessId={businessId} methodId={m.id} />
                </div>
              ))
            ) : (
              <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-center text-xs text-zinc-400">
                Belum ada metode pembayaran custom.
              </p>
            )}
          </div>

          <div className="mt-4">
            <AddPaymentMethodForm action={boundAddPaymentMethod} />
          </div>
        </div>

        {/* Printer Dapur & Bar (F&B only) */}
        {isFnb && (
          <div className="mt-6 rounded-2xl border border-zinc-200 bg-white p-5">
            <h2 className="text-sm font-semibold text-zinc-900">Printer Dapur &amp; Bar</h2>
            <p className="mt-1 text-xs text-zinc-500">
              Cetak order otomatis ke printer dapur/bar sesuai kategori menu — bukan ke kasir.
            </p>

            <div className="mt-4 space-y-2">
              {printers.length > 0 ? (
                printers.map((p) => (
                  <div key={p.id} className="rounded-xl border border-zinc-200 bg-white px-4 py-3">
                    <div className="flex items-center justify-between">
                      <p className="text-sm font-medium text-zinc-900">{p.name}</p>
                      <DeletePrinterButton businessId={businessId} printerId={p.id} />
                    </div>
                    <p className="mt-0.5 text-xs text-zinc-500">
                      {p.connection_type === "lan" ? "🌐 LAN/Wi-Fi" : "📶 Bluetooth"}
                      {p.address ? ` · ${p.address}` : ""}
                    </p>
                    {p.categories.length > 0 && (
                      <p className="mt-1 text-[11px] text-zinc-400">
                        Kategori: {p.categories.join(", ")}
                      </p>
                    )}
                  </div>
                ))
              ) : (
                <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-4 text-center text-xs text-zinc-400">
                  Belum ada printer dapur/bar. Order akan tetap dicetak di kasir saja.
                </p>
              )}
            </div>

            <div className="mt-4 border-t border-zinc-100 pt-4">
              <AddPrinterForm action={boundAddKitchenPrinter} categories={productCategories} />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

-- Module 5: tables, self_orders, self_order_items, kitchen_printers,
-- custom_payment_methods — F&B supporting features.

create table public.custom_payment_methods (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  name text not null
);

create index custom_payment_methods_business_id_idx on public.custom_payment_methods (business_id);

alter table public.custom_payment_methods enable row level security;

create policy "Owner manages custom payment methods of own businesses"
on public.custom_payment_methods for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

-- Kitchen printers -------------------------------------------------------------

create table public.kitchen_printers (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  name text not null,
  categories text[] not null default '{}',
  connection_type text not null default 'bluetooth' check (connection_type in ('bluetooth', 'lan')),
  address text
);

create index kitchen_printers_business_id_idx on public.kitchen_printers (business_id);

alter table public.kitchen_printers enable row level security;

create policy "Owner manages kitchen printers of own businesses"
on public.kitchen_printers for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

-- Tables (self-order, F&B) -----------------------------------------------------

create table public.tables (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  name text not null,
  qr_slug text not null unique
);

create index tables_business_id_idx on public.tables (business_id);

alter table public.tables enable row level security;

create policy "Owner manages tables of own businesses"
on public.tables for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

-- Now that public.tables exists, wire up the deferred FK from transactions.
alter table public.transactions
  add constraint transactions_table_id_fkey
  foreign key (table_id) references public.tables (id) on delete set null;

create index transactions_table_id_idx on public.transactions (table_id);

-- Self orders --------------------------------------------------------------

create table public.self_orders (
  id uuid primary key default gen_random_uuid(),
  business_id uuid not null references public.businesses (id) on delete cascade,
  table_id uuid not null references public.tables (id) on delete cascade,
  status text not null default 'baru' check (status in ('baru', 'diproses', 'selesai')),
  created_at timestamptz not null default now()
);

create index self_orders_business_id_idx on public.self_orders (business_id);
create index self_orders_table_id_idx on public.self_orders (table_id);

alter table public.self_orders enable row level security;

create policy "Owner manages self orders of own businesses"
on public.self_orders for all
using (private.owns_business(business_id))
with check (private.owns_business(business_id));

-- Self order items -----------------------------------------------------------

create table public.self_order_items (
  id uuid primary key default gen_random_uuid(),
  self_order_id uuid not null references public.self_orders (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  name text not null,
  price numeric(12, 2) not null,
  qty numeric(12, 2) not null,
  note text
);

create index self_order_items_self_order_id_idx on public.self_order_items (self_order_id);

alter table public.self_order_items enable row level security;

create policy "Owner manages self order items of own businesses"
on public.self_order_items for all
using (
  exists (
    select 1 from public.self_orders so
    where so.id = self_order_items.self_order_id
      and private.owns_business(so.business_id)
  )
)
with check (
  exists (
    select 1 from public.self_orders so
    where so.id = self_order_items.self_order_id
      and private.owns_business(so.business_id)
  )
);

