67	    return products.filter((p) => p.name.toLowerCase().includes(q));
68	  }, [search, products]);
69	
70	  const subtotal = cart.reduce((sum, item) => sum + item.price * item.qty, 0);
71	  const receivedAmount = Number(received) || 0;
72	  const change = paymentMethod === "Tunai" ? receivedAmount - subtotal : 0;
73	
74	  function addToCart(product: Product) {
75	    setCart((prev) => {
76	      const existing = prev.find((i) => i.productId === product.id);
