92	    setCart((prev) =>
93	      prev
94	        .map((i) =>
95	          i.productId === productId
96	            ? { ...i, qty: Math.min(i.maxStock, Math.max(0, i.qty + delta)) }
97	            : i,
98	        )
99	        .filter((i) => i.qty > 0),
100	    );
101	  }
102	
103	  function removeFromCart(productId: string) {
104	    setCart((prev) => prev.filter((i) => i.productId !== productId));
105	  }
106	
107	  async function handleConfirmPayment() {
108	    setError(null);
109	
110	    if (paymentMethod === "Tunai" && receivedAmount < subtotal) {
111	      setError("Uang diterima kurang dari total belanja.");
112	      return;
