      className="rounded-lg border border-zinc-200 px-2.5 py-1 text-[11px] font-medium text-zinc-600 transition-colors hover:border-brand-300 hover:text-brand-700"
    >
      {copied ? "✓ Tersalin" : "Salin Link"}
    </button>
  );
}

