            Link atau QR code ini sudah tidak berlaku. Silakan hubungi staf untuk QR yang
            baru.
          </p>
        </div>
      </div>
    );
  }

  const menu = data as Menu;

  return (
    <OrderScreen
      qrSlug={qrSlug}
      businessName={menu.business_name}
      tableName={menu.table_name}
      products={menu.products}
    />
  );
}

