  const supabase = await createClient();
  const { error } = await supabase.rpc("create_cashier", {
    p_business_id: businessId,
    p_name: name,
    p_role: role,
    p_pin: pin,
  });

  if (error) {
    return { error: error.message };
  }

  revalidatePath(`/business/${businessId}/cashiers`);
  return { error: null };
