    business_id: businessId,
    date,
    category,
    amount,
    note: note || null,
    ingredient_id: ingredientId,
    product_id: productId,
    qty,
  });

  if (error) {
    return { error: error.message };
  }

  revalidatePath(`/business/${businessId}/finance`);
  return { error: null };
}

